export function calculateClassicalQuoteSearch(input: Record<string, unknown>): ClassicalQuoteSearchResult {
  const keyword = (input.keyword as string) || "";
  const classic = (input.classic as string) || "";
  const author = (input.author as string) || "";

  let quotes = QUOTES;
  if (keyword) {
    const kw = keyword.toLowerCase();
    quotes = quotes.filter(q =>
      q.quote.includes(kw) || q.explanation.includes(kw) ||
      q.tags.some(t => t.includes(kw)) || q.source.includes(kw) ||
      q.author.includes(kw) || q.chapter.includes(kw)
    );
  }
  if (classic) quotes = quotes.filter(q => q.source.includes(classic));
  if (author) quotes = quotes.filter(q => q.author.includes(author));
  if (!keyword && !classic && !author) quotes = QUOTES;

  const sources = [...new Set(quotes.map(q => q.source))];

  const items = quotes.slice(0, 20);

  // 按来源分组统计
  const sourceGroups: Record<string, number> = {};
  for (const q of QUOTES) { sourceGroups[q.source] = (sourceGroups[q.source] || 0) + 1; }
  const sourceStats = Object.entries(sourceGroups).sort(([, a], [, b]) => b - a);

  // 构建 box-drawing 摘要
  const textSummary = keyword
    ? `经典名句检索：与"${keyword}"相关的名句共${quotes.length}条，涵盖${sources.join("、")}等${sources.length}部经典。`
    : `国学经典名句大全（共${QUOTES.length}条，覆盖${[...new Set(QUOTES.map(q => q.source))].length}部经典）：涵盖四书五经/诸子百家/二十四史/唐诗宋词/古文家训等，每句含原文、出处、章节、作者、朝代、白话释义和标签分类。支持按关键词、经典名称、作者筛选。`;

  const lines: string[] = [
    `┌─ 国学经典名句 ─────────────────`,
  ];

  if (keyword || classic || author) {
    const filterDesc = [keyword && `搜索"${keyword}"`, classic && `经典：${classic}`, author && `作者：${author}`].filter(Boolean).join(" · ");
    lines.push(`│ ${filterDesc} — 共 ${quotes.length} 条匹配（显示前${items.length}条）`);
    lines.push(`│`);
    lines.push(`├─ 检索结果 ──────────────────`);
    for (let i = 0; i < items.length; i++) {
      const q = items[i];
      const sep = i < items.length - 1 ? "├" : "└";
      lines.push(`│ ${sep}─ 「${q.quote.slice(0, 35)}${q.quote.length > 35 ? "…" : ""}」`);
      lines.push(`│   《${q.source}》${q.chapter} — ${q.author}（${q.dynasty}）`);
      lines.push(`│   ${q.explanation.slice(0, 55)}${q.explanation.length > 55 ? "…" : ""}`);
    }
  } else {
    lines.push(`│ 共收录 ${QUOTES.length} 条名句，覆盖 ${sourceStats.length} 部经典`);
    lines.push(`│`);
    lines.push(`├─ 经典分布 ──────────────────`);
    for (const [src, count] of sourceStats.slice(0, 12)) {
      const bar = "█".repeat(Math.min(count, 20));
      lines.push(`│ 《${src.padEnd(6, " ")}》 ${String(count).padStart(2, " ")}条 ${bar}`);
    }
    lines.push(`│`);
    lines.push(`├─ 精品摘录 ──────────────────`);
    for (let i = 0; i < Math.min(8, items.length); i++) {
      const q = items[i];
      const sep = i < Math.min(8, items.length) - 1 ? "├" : "└";
      lines.push(`│ ${sep}─ 「${q.quote.slice(0, 30)}${q.quote.length > 30 ? "…" : ""}」`);
      lines.push(`│   —《${q.source}》${q.author}（${q.dynasty}）`);
    }
  }

  lines.push(`│`);
  lines.push(`├─ 古籍出处 ──────────────────`);
  lines.push(`│ 名句原文引自各经典通行注本：`);
  lines.push(`│ 《论语》《孟子》—— 中华书局「新编诸子集成」`);
  lines.push(`│ 《道德经》《庄子》—— 中华书局「中华经典名著全本全注全译」`);
  lines.push(`│ 《史记》—— 中华书局点校本二十四史`);
  lines.push(`│ 诗文类—— 中华书局「中国古典文学基本丛书」`);
  lines.push(`│`);
  lines.push(`└─ 检索提示 ──────────────────`);
  lines.push(`   支持关键词/经典名称/作者三维检索。`);
  lines.push(`   输入「君子」可搜修身名句，输入「史记」可览史家金言。`);
  lines.push(`   330+精选名句，每日一品，终身受益。`);
  const summary = lines.join("\n");

  const total = QUOTES.length;
  return { quotes, summary: textSummary, boxSummary: summary, total } as ClassicalQuoteSearchResult & { boxSummary: string };
}
